  // ── voicing engine (design_handoff_new_chord_ux 2026-07-21 + pedagogical
  // spec §8/§10/§11). Voicings are SETS OF ABSOLUTE PITCHES (semitones,
  // C4=60), not pitch classes — real register and octave placement, per the
  // spec's v2 correction. Each style is a standard, citable jazz-piano
  // voicing (Levine): close root position, shell R-3-7 (guide tones, inert
  // 5th dropped), rootless-A (3-5-7-9; 13-for-5 on dominants; bassist plays
  // the root — the ONE sanctioned exception to the bass-invariance rule,
  // spec §11), drop-2 (2nd voice from the top dropped an octave).
  // Non-tertian/triad qualities have no standard rootless/shell form and
  // fall back to close rather than inventing one.
export function voClose(root,q){ return (CE_IV[q]||CE_IV[""]).map(i=>60+root+i); }
export function sev4(q){ const iv=CE_IV[q]; return (iv&&iv.length>=4&&q.indexOf("sus")<0)?iv.slice(0,4):null; }
