    if(cls==="min"&&sev4(q)) iv=[10,14,15,19];        // 7-9-3-5
    else if(cls==="dom"&&sev4(q)&&q.indexOf("sus")<0) iv=[10,14,16,21];  // 7-9-3-13
    else if(cls==="maj"&&(q.indexOf("^")===0)) iv=[11,14,16,19];
    if(!iv) return null;
